    role:[q('461: calculated arrival 15:30 on Nov 19 Central; old delivery 15:00; receiver owns approval. Qaysi reschedule request?', 'Please move load 461 from 15:00 to 16:00 Central on November 19; arrival is 15:30.', 'Load 461 is confirmed from 15:00 to 16:00 Central on November 19; arrival is 15:30.', 'Please move load 462 from 15:00 to 16:00 Central on November 19; arrival is 15:30.', 'So‘rov ID, eski va yangi slot, sana/zona hamda hisoblangan sababni saqlaydi.', ['Requestni confirmed holatga aylantirgan fe’lni tekshiring.', 'Qaysi load uchun hisob qilinyapti?'], ['T2','T5','T6']),q('461: receiver now approved Nov 19, 16:00 Central, Door 3. Driver availability through 17:00. Broker va driverga qaysi update?', 'Receiver confirmed November 19 at 16:00 Central, Door 3; please read back.', 'Receiver requested November 19 at 16:00 Central, Door 3; please read back.', 'Receiver confirmed November 19 at 16:00 Central, Door 8; please read back.', 'Vakolatli approval keldi, vaqt driver limitiga mos; joy 461niki bo‘lishi kerak.', ['Oxirgi receiver xabarining statusini tekshiring.', 'Boshqa loadga tegishli joyni ajrating.'], ['T5','T7','T8','T9']),q('461: delivery approved Nov 19, 16:00 Central, Door 3. Driver replies “Nov 18, 16:00 Central, Door 3.” Qaysi correction?', 'The time and door match; the approved date is November 19.', 'The date and door match; the approved time is 16:00 Central.', 'The time and date match; the approved door is Door 3.', 'Faqat sana mos emas; check-backda shu maydon tuzatiladi.', ['Driver aytgan sana manbadagi sana bilan mosmi?', 'Qaysi maydon mos kelmayotganini bittalab solishtiring.'], ['T2','T8'])],
